=== public/styles.css ===
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --primary: #4A90E2;
  --primary-dark: #357ABD;
  --secondary: #50C878;
  --danger: #E74C3C;
  --warning: #F39C12;
  --text: #2C3E50;
  --text-light: #7F8C8D;
  --bg: #F8F9FA;
  --white: #FFFFFF;
  --border: #DFE6E9;
  --shadow: rgba(0, 0, 0, 0.1);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Header */
.header {
  background: var(--white);
  box-shadow: 0 2px 10px var(--shadow);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 0;
}

.logo {
  font-size: 1.5rem;
  color: var(--primary);
  font-weight: 700;
}

.nav {
  display: flex;
  gap: 1.5rem;
  align-items: center;
}

.nav a, .nav button.link-button {
  color: var(--text);
  text-decoration: none;
  font-weight: 500;
  transition: color 0.3s;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1rem;
  font-family: inherit;
}

.nav a:hover, .nav button.link-button:hover {
  color: var(--primary);
}

.nav .carrinho-badge {
  position: relative;
}

.nav .carrinho-badge .badge {
  position: absolute;
  top: -8px;
  right: -8px;
  background: var(--danger);
  color: var(--white);
  border-radius: 50%;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
}

/* Main */
.main {
  padding: 2rem 0;
  min-height: calc(100vh - 80px);
}

/* Buttons */
.btn {
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s;
  display: inline-block;
  text-decoration: none;
  text-align: center;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px var(--shadow);
}

.btn-success {
  background: var(--secondary);
  color: var(--white);
}

.btn-success:hover {
  background: #45B369;
  transform: translateY(-2px);
}

.btn-danger {
  background: var(--danger);
  color: var(--white);
}

.btn-danger:hover {
  background: #C0392B;
}

.btn-secondary {
  background: var(--text-light);
  color: var(--white);
}

.btn-secondary:hover {
  background: #6C7A89;
}

.btn-small {
  padding: 0.5rem 1rem;
  font-size: 0.9rem;
}

.btn-block {
  width: 100%;
  display: block;
}

/* Forms */
.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 600;
  color: var(--text);
}

.form-control {
  width: 100%;
  padding: 0.75rem;
  border: 2px solid var(--border);
  border-radius: 8px;
  font-size: 1rem;
  transition: border-color 0.3s;
  font-family: inherit;
}

.form-control:focus {
  outline: none;
  border-color: var(--primary);
}

textarea.form-control {
  resize: vertical;
  min-height: 100px;
}

select.form-control {
  cursor: pointer;
}

/* Cards */
.card {
  background: var(--white);
  border-radius: 12px;
  box-shadow: 0 2px 8px var(--shadow);
  overflow: hidden;
  transition: transform 0.3s, box-shadow 0.3s;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 20px var(--shadow);
}

.card-body {
  padding: 1.5rem;
}

.card-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--text);
}

.card-text {
  color: var(--text-light);
  margin-bottom: 1rem;
}

/* Auth Pages */
.auth-container {
  max-width: 400px;
  margin: 3rem auto;
}

.auth-card {
  background: var(--white);
  padding: 2rem;
  border-radius: 12px;
  box-shadow: 0 4px 20px var(--shadow);
}

.auth-card h2 {
  text-align: center;
  margin-bottom: 2rem;
  color: var(--primary);
}

.auth-card .form-footer {
  margin-top: 1.5rem;
  text-align: center;
}

.auth-card .form-footer a {
  color: var(--primary);
  text-decoration: none;
  font-weight: 600;
}

/* Products Grid */
.products-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
  flex-wrap: wrap;
  gap: 1rem;
}

.products-header h2 {
  font-size: 2rem;
  color: var(--text);
}

.filter-group {
  display: flex;
  gap: 1rem;
  align-items: center;
}

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
  margin-bottom: 2rem;
}

.product-card {
  cursor: pointer;
}

.product-image {
  width: 100%;
  height: 250px;
  object-fit: cover;
