/* Modal */
.modal {
  display: none;
  position: fixed;
  z-index: 1000;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  animation: fadeIn 0.3s;
}

.modal.show {
  display: flex;
  align-items: center;
  justify-content: center;
}

.modal-content {
  background-color: var(--white);
  padding: 2rem;
  border-radius: 12px;
  max-width: 600px;
  width: 90%;
  max-height: 90vh;
  overflow-y: auto;
  position: relative;
  animation: slideUp 0.3s;
}

.modal-close {
  position: absolute;
  right: 1rem;
  top: 1rem;
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-light);
  cursor: pointer;
  transition: color 0.3s;
}

.modal-close:hover {
  color: var(--text);
}

/* Notification */
.notificacao {
  position: fixed;
  top: 20px;
  right: 20px;
  padding: 1rem 1.5rem;
  border-radius: 8px;
  color: var(--white);
  font-weight: 600;
  box-shadow: 0 4px 12px var(--shadow);
  z-index: 2000;
  display: none;
  animation: slideIn 0.3s;
}

.notificacao.show {
  display: block;
}

.notificacao.success {
  background: var(--secondary);
}

.notificacao.error {
  background: var(--danger);
}

.notificacao.info {
  background: var(--primary);
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(50px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(100px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* Responsive */
@media (max-width: 768px) {
  .header-content {
    flex-direction: column;
    gap: 1rem;
  }

  .nav {
    width: 100%;
    justify-content: center;
    flex-wrap: wrap;
  }

  .products-grid {
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 1rem;
  }

  .product-detail {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .cart-item {
    grid-template-columns: 80px 1fr;
    gap: 1rem;
  }

  .cart-item-actions {
    grid-column: 1 / -1;
    flex-direction: row;
    justify-content: space-between;
  }

  .order-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .order-item {
    grid-template-columns: 60px 1fr;
  }

  .order-item-price {
    grid-column: 1 / -1;
    text-align: left;
    margin-top: 0.5rem;
  }

  .admin-table {
    overflow-x: auto;
  }

  .admin-table table {
    min-width: 600px;
  }

  .modal-content {
    width: 95%;
    padding: 1.5rem;
  }
}

@media (max-width: 480px) {
  .products-grid {
    grid-template-columns: 1fr;
  }

  .product-detail-info h1 {
    font-size: 1.75rem;
  }

